                    "(1u << n). Empat operasi dasarnya:",
                    "",
                    "  set     reg |=  (1u << n);    bit n jadi 1, bit lain tetap",
                    "  clear   reg &= ~(1u << n);    bit n jadi 0, bit lain tetap",
                    "  toggle  reg ^=  (1u << n);    bit n dibalik, bit lain tetap",
                    "  baca    (reg >> n) & 1u       hasilnya 0 atau 1",
                    "",
                    "Kenapa bit lain aman? OR dengan 0 nggak mengubah apa pun, AND",
                    "dengan 1 nggak mengubah apa pun, dan XOR dengan 0 juga nggak",
                    "mengubah apa pun. Topeng (1u << n) cuma punya satu bit 1, jadi",
                    "cuma bit itu yang kena. Untuk clear, topengnya dibalik dulu pakai",
                    "~ sehingga semua bit bernilai 1 kecuali bit n.",
                    "",
                    "Supaya lebih enak dibaca, banyak kode firmware membuat makro",
                    "BIT(n). Program di bawah memakainya untuk keempat operasi.",
