                    "anggapan itu benar. Untuk register, salah: isinya bisa berubah",
                    "kapan saja karena perangkat keras.",
                    "",
                    "Ambil contoh loop yang menunggu bit siap di register status:",
                    "",
                    "  while ((STATUS & SIAP) == 0) { }",
                    "",
                    "Tanpa volatile, compiler yang mengoptimasi (misalnya dengan -O2)",
                    "boleh membaca STATUS sekali saja lalu mengulang hasil lama itu",
                    "selamanya. Loop-nya nggak pernah selesai. Kebalikannya juga",
                    "terjadi: dua tulisan berturut-turut ke register yang sama bisa",
                    "dibuang salah satunya karena dianggap sia-sia.",
                    "",
