                    "tulis ke objek itu harus dikerjakan sungguhan, sebanyak dan",
                    "seurut yang ditulis di kode. Di PC nggak ada register GPIO, jadi",
                    "program di bawah memakai variabel biasa yang diakses lewat pointer",
                    "volatile, persis gaya firmware.",
