                    "untuk membedakannya:",
                    "  1. Sisakan satu slot yang nggak pernah diisi. Buffer dianggap penuh",
                    "     kalau kepala tinggal satu langkah di belakang ekor. Gampang, tapi",
                    "     buffer 8 slot cuma bisa memuat 7 byte.",
