                    "     itu diubah ISR dan loop utama sekaligus, jadi rawan bentrok.",
                    "  3. Biarkan kepala dan ekor terus bertambah tanpa dikembalikan ke 0,",
                    "     lalu pakai ukuran pangkat dua. Posisi slot dihitung dengan",
                    "     kepala & 7, dan isi buffer adalah kepala - ekor.",
                    "",
                    "Cara ketiga memakai sifat bilangan tak bertanda: uint8_t yang lewat",
                    "255 kembali ke 0, dan selisih dua uint8_t tetap benar walau salah",
                    "satunya sudah melingkar. Misalnya kepala 2 dan ekor 254:",
