                    "diserahkan ke Eclipse Foundation dan dibuka sebagai open source.",
                    "VxWorks buatan Wind River adalah RTOS komersial yang lama dipakai di",
                    "industri dirgantara. NuttX dikelola Apache Software Foundation, dan",
