            {
                "heading": "Kenapa ada register BSRR",
                "body": [
                    "Di latihan Driver GPIO dengan Register Tiruan, kamu mengubah",
                    "satu pin lewat ODR dengan pola baca, ubah, tulis. Pola itu",
                    "punya celah. Kalau interupsi datang di antara baca dan tulis,",
                    "lalu interupsi itu juga mengubah ODR, perubahannya tertimpa",
                    "waktu kode utama menulis balik salinan lamanya.",
                    "",
                    "STM32 menutup celah itu dengan register BSRR (bit set/reset",
                    "register). Menulis 1 di bit n menyalakan pin n, menulis 1 di",
                    "bit n + 16 mematikannya, dan bit bernilai 0 nggak mengubah",
                    "apa-apa. Satu kali tulis, tanpa membaca dulu. Program di bawah",
                    "meniru keduanya dengan register tiruan.",
                ],
            },
            {
                "heading": "Contoh: ODR lawan BSRR",
                "code": "#include <stdio.h>\n#include <stdint.h>\n#include <inttypes.h>\n\n/* Register tiruan bergaya STM32. Di chip asli keduanya alamat tetap. */\nstatic uint32_t ODR;   /* output data register: bit n = pin n */\n\n/* BSRR: tulis 1 di bit 0-15 menyalakan pin itu,\n * tulis 1 di bit 16-31 mematikan pin (n - 16). Bit bernilai 0 diabaikan. */\nstatic void tulis_BSRR(uint32_t nilai)\n{\n    uint32_t nyala = nilai & 0xFFFFu;\n    uint32_t mati  = nilai >> 16;\n    ODR = (ODR | nyala) & ~mati;   /* di chip, perangkat keras yang melakukannya */\n}\n\n/* \"Interupsi\" yang menyalakan pin 3 (misalnya LED tanda data masuk). */\nstatic void interupsi_rmw(void)  { ODR |= 1u << 3; }\nstatic void interupsi_bsrr(void) { tulis_BSRR(1u << 3); }\n\nint main(void)\n{\n    /* Cara 1: read-modify-write ODR, disela interupsi di tengahnya. */\n    ODR = 0x00000021u;                     /* pin 0 dan 5 menyala */\n    uint32_t salinan = ODR;                /* 1. baca */\n    interupsi_rmw();                       /*    interupsi datang di sini */\n    salinan &= ~(1u << 5);                 /* 2. ubah: matikan pin 5 */\n    ODR = salinan;                         /* 3. tulis balik */\n    printf(\"ODR lewat RMW : 0x%08\" PRIX32 \" (pin 3 hilang)\\n\", ODR);\n\n    /* Cara 2: BSRR, satu tulisan, nggak ada celah untuk disela. */\n    ODR = 0x00000021u;\n    interupsi_bsrr();                      /* boleh datang kapan saja */\n    tulis_BSRR(1u << (5 + 16));            /* matikan pin 5 */\n    printf(\"ODR lewat BSRR: 0x%08\" PRIX32 \" (pin 3 tetap)\\n\", ODR);\n    return 0;\n}",
            },
