                    "baca belum tahu interupsi sudah menyalakan pin 3, jadi pin 3",
                    "ikut padam. Lewat BSRR, setiap pihak cuma menyentuh bitnya",
                    "sendiri. HAL_GPIO_WritePin pun memakai BSRR di dalamnya.",
                    "",
