                    "menulis register di semua tempat. Ukur dulu bagian mana yang",
                    "lambat. Biasanya cuma satu dua fungsi yang perlu diturunkan ke",
                    "LL atau register, dan sisanya tetap HAL supaya mudah dirawat.",
